/** Every screen, flattened, in rail order. */
export const NAV_ITEMS: readonly NavItem[] = NAV_GROUPS.flatMap((group) => group.items);

/** Routes that render inside the game shell. */
export const GAME_ROUTES: readonly string[] = NAV_ITEMS.map((item) => item.href);

/** The screen a session lands on. */
export const HOME_ROUTE = '/command-centre';

/** Look a screen up by pathname; returns null for the landing and auth pages. */
export function navItemFor(pathname: string): NavItem | null {
  return NAV_ITEMS.find((item) => pathname === item.href || pathname.startsWith(`${item.href}/`)) ?? null;
}

/** The group a pathname belongs to, or null. */
export function navGroupFor(pathname: string): NavGroup | null {
  return NAV_GROUPS.find((group) => group.items.some((item) => pathname === item.href || pathname.startsWith(`${item.href}/`))) ?? null;
}

/** True when the shell chrome (rail + status bar) should render for this path. */
export function isGamePath(pathname: string): boolean {
  return navItemFor(pathname) !== null;
}
